<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class DormitoryOperationsController extends Controller{
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('dormitory_manager')||$r->user()->canDo('dormitory.manage'),403);}
public function operations(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$incidents=DB::table('dormitory_incidents as i')->join('students as s','s.id','=','i.student_id')->where('i.academic_period_id',$p->id)->select('i.*','s.last_name','s.first_name')->orderByDesc('i.occurred_at')->get();$aways=DB::table('dormitory_absences as a')->join('dormitory_stays as st','st.id','=','a.dormitory_stay_id')->join('students as s','s.id','=','st.student_id')->whereNull('a.returned_at')->select('a.*','s.last_name','s.first_name')->orderBy('a.expected_back_at')->get();$stays=DB::table('dormitory_stays as st')->join('students as s','s.id','=','st.student_id')->where('st.status','active')->select('st.id','s.last_name','s.first_name')->orderBy('s.last_name')->get();return view('dormitory.operations',compact('incidents','aways','stays'));}
public function absence(Request $r){$this->manage($r);$d=$r->validate(['dormitory_stay_id'=>'required|exists:dormitory_stays,id','left_at'=>'required|date','expected_back_at'=>'nullable|date','destination'=>'nullable|string|max:500','note'=>'nullable|string|max:3000']);DB::table('dormitory_absences')->insert($d+['created_at'=>now(),'updated_at'=>now()]);return back();}
public function returned(Request $r,$id){$this->manage($r);DB::table('dormitory_absences')->where('id',$id)->whereNull('returned_at')->update(['returned_at'=>now(),'updated_at'=>now()]);return back();}
public function incident(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$d=$r->validate(['student_id'=>'required|exists:students,id','occurred_at'=>'required|date','type'=>'required|in:violation,reward,conflict,damage,other','severity'=>'required|in:normal,high,critical','description'=>'required|string|max:5000','action_taken'=>'nullable|string|max:5000']);DB::table('dormitory_incidents')->insert($d+['academic_period_id'=>$p->id,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function finance(Request $r){$this->manage($r);$rows=DB::table('dormitory_charges as c')->join('dormitory_stays as st','st.id','=','c.dormitory_stay_id')->join('students as s','s.id','=','st.student_id')->select('c.*','s.last_name','s.first_name')->orderByDesc('c.period')->get();$stays=DB::table('dormitory_stays as st')->join('students as s','s.id','=','st.student_id')->where('st.status','active')->select('st.id','s.last_name','s.first_name')->orderBy('s.last_name')->get();return view('dormitory.finance',compact('rows','stays'));}
public function charge(Request $r){$this->manage($r);$d=$r->validate(['dormitory_stay_id'=>'required|exists:dormitory_stays,id','period'=>'required|string|max:20','amount'=>'required|numeric|min:0','due_on'=>'nullable|date','document_number'=>'nullable|string|max:100']);DB::table('dormitory_charges')->updateOrInsert(['dormitory_stay_id'=>$d['dormitory_stay_id'],'period'=>$d['period']],$d+['updated_at'=>now(),'created_at'=>now()]);return back();}
public function pay(Request $r,$id){$this->manage($r);$x=DB::table('dormitory_charges')->find($id);abort_if(!$x,404);$d=$r->validate(['paid_amount'=>'required|numeric|min:0']);$paid=min((float)$x->amount,(float)$d['paid_amount']);DB::table('dormitory_charges')->where('id',$id)->update(['paid_amount'=>$paid,'status'=>$paid>=(float)$x->amount?'paid':'partial','paid_at'=>$paid>=(float)$x->amount?now():null,'updated_at'=>now()]);return back();}
public function report(Request $r){$this->manage($r);$buildings=DB::table('dormitory_buildings as b')->where('b.active',1)->get()->map(function($b){$roomIds=DB::table('dormitory_rooms')->where('dormitory_building_id',$b->id)->pluck('id');$b->rooms=$roomIds->count();$b->places=DB::table('dormitory_places')->whereIn('dormitory_room_id',$roomIds)->count();$b->free=DB::table('dormitory_places')->whereIn('dormitory_room_id',$roomIds)->where('status','available')->count();$b->occupied=$b->places-$b->free;return $b;});$debt=DB::table('dormitory_charges')->selectRaw('SUM(amount-paid_amount) debt')->whereIn('status',['unpaid','partial'])->value('debt')??0;return view('dormitory.report',compact('buildings','debt'));}
}